{
  const mk = () => new DocumentRepository([
    { id: 'own', tenant: 'a', owner: 'e', deleted: false, archived: false },
    { id: 'other', tenant: 'a', owner: 'x', deleted: false, archived: false },
    { id: 'gone', tenant: 'a', owner: 'e', deleted: true, archived: false },
    { id: 'foreign', tenant: 'b', owner: 'e', deleted: false, archived: false },
    { id: 'done', tenant: 'a', owner: 'x', deleted: false, archived: true },
  ]);
  const r = mk(); const s = new DocumentService(r);
  const editor = { tenant: 'a', user: 'e', role: 'editor' };
  const viewer = { tenant: 'a', user: 'e', role: 'viewer' };
  const adm = { tenant: 'a', user: 'adm', role: 'admin' };
  const snap = () => JSON.stringify([r.documents, r.audit]);
  const before = snap();
  for (const id of ['gone', 'foreign', 'missing']) assert.throws(() => s.archive(adm, id), /^Error: not found$/);
  assert.throws(() => s.archive(editor, 'other'), /^Error: forbidden$/);
  assert.throws(() => s.archive(viewer, 'own'), /^Error: forbidden$/);
  assert.throws(() => s.archive(viewer, 'done'), /^Error: forbidden$/);
  assert.throws(() => s.archive(editor, 'done'), /^Error: forbidden$/);
  assert.equal(snap(), before);
  s.archive(editor, 'own');
  s.archive(adm, 'other');
  s.archive(adm, 'done');
